if MODE == "--flowcopy" and not any(f.startswith("闸⑩") for f in fails):
    fails.append("闸⑩（拆红模式 --flowcopy）注入的两处漂移一条都没抓到：这一档是恒绿的，"
                 "它对『名单漂了』零反应，那么它拦不住任何一次手抄")

# 闸⑪：v5 那条 CI 腿的分母不许是口味（第二十发还的债）。
# 这条腿写的是"出界幅度 > 配对步长 CI 的半宽"，而它**声称**在测的是"这一步自己的 CI 不含 0"。
# 两者只在区间以点估计为中点时等价——那句前提此前只活在注释里，所以它必须当场可核：
#   腿 A 对称性：档案里的 CI 中点离点估计不许超过 sf.CI_CENTER_TOL（= 一位小数的两倍舍入）；
#   腿 B 分子同一性：那条腿比的"出界幅度"必须就是这一步自己的点估计（差只许来自各自舍入，0.25 张）；
#   腿 C 等价性：拿**当前模式下的规则实现**问一遍它判成承重没有，答案必须等于"CI 不含 0"
#     （所以 --v5strict 把分母换成全宽时，红的是这条腿，红的内容是"实现与它声称的命题分家"，
#      而不是上一轮那种"某本账的判词变了"——那是后果，不是理由）；
#   腿 D 双记账：凡档案自带 ci_leg_reading（由训练路径那段代码写的）的，守卫必须能独立复算出同一份，
#     全册一本都没有 ⇒ 这条腿只被守卫自己核过、实现侧没人管 ⇒ 算红，不算通过。
# 参评集合与闸⑧ **不同**：闸⑧ 只评"记录在 v4 名下且阶梯顶在账"的那几本，这一闸评所有记了配对步长的账
# （两闸数的是不同的东西，混在一起会各自都看不出对方漏了什么）。
print("\n[闸⑪ v5 那条 CI 腿 == 「配对步长 CI 不含 0」，且它的前提（区间对称）当场可核]")
if MODE == "--ciasym":
    inj = [p for p in docs if p.endswith(MUST_STAY)]
    for p in inj:
        ci = docs[p]["paired_step_small_to_anchor"]["ci95_imgs"]
        ci[1] = round(float(ci[1]) + 40.0, 1)     # 只动上端：区间不再以点估计为中点
    print(f"  （拆红注入）给 {MUST_STAY} 的 CI 上端 +40 张 ⇒ 中点漂移、且「> 半宽」与「不含 0」分家")
if MODE == "--ciunread":
    stripped = [p for p in docs if (docs[p].get("verdict") or {}).pop("ci_leg_reading", None) is not None]
    print(f"  （拆红注入）抹掉 {len(stripped)} 本账的 ci_leg_reading ⇒ 双记账那条腿退回「只有守卫核得到」")
    if not stripped:
        fails.append("闸⑪（拆红模式 --ciunread）全册一本双记账都抹不到 ⇒ 这一档现在是空转的："
                     "落地本还没入库，『抹掉它该红』这件事此刻没有被测过")
n11 = n11_double = 0
for name, d in sorted(docs.items()):
    ps = d.get("paired_step_small_to_anchor")
    v = d.get("verdict") or {}
    if not isinstance(ps, dict) or ps.get("mean_gap_imgs") is None or not ps.get("ci95_imgs"):
        continue
    lo, hi = (float(x) for x in ps["ci95_imgs"])
    m = float(ps["mean_gap_imgs"])
    half = (hi - lo) / 2
    book = name.split(chr(92))[-1]
    n11 += 1
    off = abs((lo + hi) / 2 - m)
    if off > sf.CI_CENTER_TOL:
        fails.append(f"闸⑪ {book}：CI [{lo:+.1f}, {hi:+.1f}] 的中点离点估计 {m:+.1f} 有 {off:.2f} 张 > 容差 "
                     f"{sf.CI_CENTER_TOL:g} ⇒ 这条腿的分母不再是它的 margin，「> 半宽」与「不含 0」不再等价")
    gap_oob = abs(m) if v.get("oob_gap_imgs") is None else float(v["oob_gap_imgs"])
    if abs(gap_oob - abs(m)) > 0.25:
        fails.append(f"闸⑪ {book}：那条腿比的出界幅度是 {gap_oob} 张，而这一步自己的点估计是 {m} 张"
                     "⇒ 比的不是同一个量（差超过两处一位小数舍入之和 0.25 张）")
    # 必须把模块全局显式喂进去：`full_width` 是 oob_resolution 的**入参**，它自己不读 FULL_WIDTH_MODE，
    # 裸调用会永远拿半宽 ⇒ --v5strict 之下这条腿假绿（"走实现"这句话就成了注释）。
    load_rule = gap_oob > sf.oob_resolution(ps, full_width=bool(sf.FULL_WIDTH_MODE))
    load_ci = bool(lo > 0 or hi < 0)
    if load_rule != load_ci:
        fails.append(f"闸⑪ {book}：规则实现判「{('承重' if load_rule else '不承重')}」而 CI 不含 0 判"
                     f"「{('承重' if load_ci else '不承重')}」⇒ 实现与它声称的命题分家"
                     + ("（这正是把分母换成全宽的后果：板块没有任何一句话要用 |均值| > hi−lo）"
                        if MODE == "--v5strict" else ""))
    dbl = v.get("ci_leg_reading")
    if isinstance(dbl, dict):
        n11_double += 1
        want = sf.ci_leg_reading(ps, gap_oob)
        diff = {k: (dbl.get(k), want.get(k)) for k in set(dbl) | set(want) if dbl.get(k) != want.get(k)}
        if diff:
            fails.append(f"闸⑪ {book}：档案自带的双记账与守卫复算不一致 {diff}"
                         "⇒ 训练路径那段代码与守卫读的不是同一把尺子")
if n11 == 0:
    fails.append("闸⑪ 一本记了配对步长的账都没有——不是通过，是没测到")
elif n11_double == 0:
    fails.append(f"闸⑪ {n11} 本参评账没有一本自带 ci_leg_reading 双记账 ⇒ 这条腿的口径只被守卫自己核过，"
                 "产出它的那段代码没有把『我在测什么』写进档案（修复还没落到盘上）")
else:
    print(f"  参评 {n11} 本（每本一条小→锚配对步长）；其中 {n11_double} 本自带双记账且与守卫复算逐字段相同")
if MODE == "--ciasym" and not any("中点离点估计" in f or "分家" in f for f in fails):
    fails.append("闸⑪（拆红模式 --ciasym）注入的非对称 CI 一条都没抓到：这一档恒绿，"
                 "它拦不住『区间不对称却仍用半宽当 margin』")
if MODE == "--ciunread" and not any("双记账" in f for f in fails):
    fails.append("闸⑪（拆红模式 --ciunread）抹掉双记账之后没红：说明『至少一本自带双记账』那句是句空话")

if MODE == "--famblind" and not (any(f.startswith("闸⑤") for f in fails)
                                 and any("家族位" in f for f in fails)):
    fails.append("闸⑤＋闸⑨（拆红模式 --famblind）两条腿没同时红：既要有『跨族当成重跑』的逐位红，"
                 "又要有『档案名与 student_arch 不同族』的红——少一条就是 CNN 那本还没入库或守卫根本没读族，"
                 "此档等于没测到，不许记成通过")

if MODE == "--g5drop" and not any(f.startswith("闸⑤ 候选账不平") for f in fails):
    fails.append("闸⑤（拆红模式 --g5drop）『候选必须有归属』那条守恒账没红：要么那句计数已经不再被打印"
                 "（那这条拆红档就是恒绿的装饰），要么丢掉的这本被别的退出路径接住了——两种都不是通过，"
                 "此档等于没测到，不许记成通过")

# 闸⑫：档案里的自我限定句子，不许是"没渲染的模板"（第二十一发现的两处自伤）。
# 踩中的东西很具体：`step4b_seed_variance.py` 有一句 limitations 漏了 f 前缀，于是那本账把自己
# 的复现单位打印成了字面量 `{len(seeds)}`。这类 bug 不会让它任何数字变红——训练照样跑、
# CI 照样算、判词照样自证——它只把"这本账知道自己底是欠估"那句话变成一句没人读过的代码文本。
# 所以它不并进判据类闸（⑤–⑪ 判的是数字出自哪批流、比值等价于什么），单立一道**文本闸**，
# 但按第十五发那条规矩**每一腿都得有自己的专属红**（`--unformatted` 钉腿 A、`--wrongcount` 钉腿 B）：
# 没有专属红的腿，就是恒绿的装饰。
#   腿 A 残留：任何字符串字段里出现 `{…}` 且花括号内像代码（`标识符(`、含下标或引号）⇒ 红；
#   腿 B 补渲染补错数：凡 limitations 里那句"种子底由 N 个点的极差估"，N 必须等于该本自己的
#     len(seeds)——钉的是"把数填进句子时填了别的账的数"那一类。**反面要如实说**：本轮真的自伤过一次
#     （补渲染的脚本把三本没坏的账那句措辞从"欠估"改成了"仍是欠估"），那一处**不留花括号、也不改数**，
#     腿 A、腿 B 都抓不到它 ⇒ 这类只改措辞的误伤当前只有 `git diff` 加人眼这一道防线，别把它记成有闸。
#   分母自证：全册 80 本、展开的字符串字段条数必须现读打印；读到 0 条 ⇒ 扫描器本身失效，算红。
print("\n[闸⑫ 档案文本里没有未渲染的占位符，且『种子底由 N 个点』那句的 N == 该本自己的 len(seeds)]")
BRACE = re.compile(r"\{([^{}]*)\}")


def _looks_like_code(inner):
    """花括号里剩的是不是**表达式**：以裸标识符开头才算残留（`{len(seeds)}` / `{hw_ratio}` / `{d['x']}`）。
    第二十六发在真产物上抓到本闸第一条假红：f-string 渲染出的 dict repr `{'档 × α': 0.692, ...}` 带引号，
    被旧口径（"有引号/有方括号就算代码"）当成没渲染。旧口径另有一条假绿——裸标识符 `{hw_ratio}`
    既没引号也没括号，它根本抓不到 ⇒ 两头各有一条专属红，见 `--bareid`。
    """
    return bool(re.match(r"[A-Za-z_]\w*(?:[.!([:].*)?$", inner.strip()))


def _walk(node, path=""):
    if isinstance(node, dict):
        for k, v in node.items():
            yield from _walk(v, f"{path}.{k}")
    elif isinstance(node, list):
        for i, v in enumerate(node):
            yield from _walk(v, f"{path}[{i}]")
    elif isinstance(node, str):
        yield path, node


arch_all = {}
for path in sorted(glob.glob("compress_report_v*.json")):
    arch_all[path] = json.loads(open(path, encoding="utf-8").read())
if MODE == "--unformatted":
    hit = 0
    for book, d in sorted(arch_all.items()):
        for i, s in enumerate(d.get("limitations") or []):
            if isinstance(s, str) and "种子底由" in s and "个点" in s:
                d["limitations"][i] = re.sub(r"(种子底由 )\d+( 个点)", r"\1{len(seeds)}\2", s)
                hit += 1
    print(f"  （拆红注入）把 {hit} 本账的种子底那句退回漏 f 的形状 ⇒ 全册应读到 {hit} 处花括号残留")
    if hit == 0:
        fails.append("闸⑫（拆红模式 --unformatted）注入腿找不到任何一本带『种子底由 N 个点』的账 ⇒ "
                     "这一档现在是空转的：腿 A 此刻没有被测过，不许记成通过")
if MODE == "--wrongcount":
    picked = None
    for book, d in sorted(arch_all.items()):
        if not isinstance(d.get("seeds"), list):
            continue
        for i, s in enumerate(d.get("limitations") or []):
            m = isinstance(s, str) and re.search(r"(种子底由 )(\d+)( 个点)", s)
            if m:
                wrong = int(m.group(2)) + 1
                d["limitations"][i] = f"{m.group(1)}{wrong}{m.group(3)}"
                picked = f"{book.split(chr(92))[-1]}（{m.group(2)} → {wrong}，seeds 实为 {len(d['seeds'])} 条）"
                break
        if picked:
            break
    print(f"  （拆红注入）把 {picked or '（没有一本可注入）'} 的那句改成错数 ⇒ 花括号一个都没多，"
          "只有腿 B 看得见")
    if not picked:
        fails.append("闸⑫（拆红模式 --wrongcount）找不到『种子底由 N 个点 + seeds 是列表』的账可注入 ⇒ "
                     "腿 B 此刻是空转的，不许记成通过")
BAREID_HIT = ""
if MODE == "--bareid":
    # 判别器改写后的两条腿一次测完（第二十六发：旧口径一头假红、一头假绿）：
    #   腿 A' 已渲染的 dict repr 必须**不红**（红了 = 那条假红没修掉）
    #   腿 B' 裸标识符残留必须**红**（不红 = 旧口径那条假绿还在，{hw_ratio} 形状漏网）
    INJ_A = "（拆红注入·已渲染值）半宽比 {'低数据2000 × α=0.3': 0.692, '满数据8500 × α=1': 1.014}"
    INJ_B = "（拆红注入·裸标识符残留）半宽比 {hw_ratio}"
    for book, d in sorted(arch_all.items()):
        lims = d.get("limitations")
        if isinstance(lims, list) and len(lims) >= 2 and isinstance(lims[0], str) \
                and isinstance(lims[-1], str):
            lims[0] = f"{lims[0]} {INJ_A}"        # 只往字符串里加形状，不改条数（条数是别的账的读数）
            lims[-1] = f"{lims[-1]} {INJ_B}"
            BAREID_HIT = book.split(chr(92))[-1]
            break
    print(f"  （拆红注入 --bareid）在 {BAREID_HIT or '（没有一本可注入）'} 的 limitations 首末两条"
          "各接一种花括号形状：已渲染的 dict repr（必须不红）+ 裸标识符残留（必须红）")
    if not BAREID_HIT:
        fails.append("闸⑫（拆红模式 --bareid）找不到 limitations ≥ 2 条的账可注入 ⇒ 两腿此刻都是空转的，"
                     "不许记成通过")
n12_books = n12_str = 0
n12_seed_sent = n12_seed_bad = 0
for book, d in sorted(arch_all.items()):
    name = book.split(chr(92))[-1]
    n12_books += 1
    for field, s in _walk(d):
        n12_str += 1
        for inner in BRACE.findall(s):
            if _looks_like_code(inner):
                fails.append(f"闸⑫ {name}{field}：读到未渲染的占位符 {{{inner}}} ⇒ 这本账的自我限定"
                             "是一条代码文本而不是句子（写它的句子漏了 f 前缀）")
    for s in d.get("limitations") or []:
        if not isinstance(s, str):
            continue
        m = re.search(r"种子底由 (\d+) 个点的极差估", s)
        if m:
            n12_seed_sent += 1
            seeds = d.get("seeds")
            if isinstance(seeds, list) and int(m.group(1)) != len(seeds):
                n12_seed_bad += 1
                fails.append(f"闸⑫ {name}：那句写的是 {m.group(1)} 个点，而这本自己的 seeds 有 "
                             f"{len(seeds)} 条 ⇒ 补渲染补错了本（数字是从别的账抄来的）")
if n12_books == 0 or n12_str == 0:
    fails.append(f"闸⑫ 全册读到 {n12_books} 本 / {n12_str} 条字符串 ⇒ 扫描器根本没展开档案，"
                 "这一档等于没测到，不许记成通过")
else:
    print(f"  分母自证：全册 {n12_books} 本、展开 {n12_str} 条字符串字段；"
          f"其中 {n12_seed_sent} 本带『种子底由 N 个点』那句，N 与各自 len(seeds) 对不上的有 {n12_seed_bad} 本")
if MODE == "--unformatted" and not any(f.startswith("闸⑫") and "占位符" in f for f in fails):
    fails.append("闸⑫（拆红模式 --unformatted）注入了花括号却没读到红：腿 A 恒绿，"
                 "它拦不住下一次漏 f（此档等于没测到，不许记成通过）")
if MODE == "--wrongcount":
    if not any(f.startswith("闸⑫") and "补错了本" in f for f in fails):
        fails.append("闸⑫（拆红模式 --wrongcount）改了数却没读到红：腿 B 恒绿，"
                     "『N 必须等于该本自己的 len(seeds)』那句是空话（此档等于没测到，不许记成通过）")
    if any(f.startswith("闸⑫") and "占位符" in f for f in fails):
        fails.append("闸⑫（拆红模式 --wrongcount）腿 A 也红了：注入进去的还是花括号形状 ⇒ 两腿没分离，"
                     "这一档其实只是 --unformatted 的重复，它没有带来新被测对象")
if MODE == "--bareid" and BAREID_HIT:
    ph_red = [f for f in fails if f.startswith("闸⑫") and "占位符" in f]
    if not any("hw_ratio" in f for f in ph_red):
        fails.append("闸⑫（拆红模式 --bareid）裸标识符残留 {hw_ratio} 没被抓到 ⇒ 判别器那条假绿还在"
                     "（旧口径要引号或括号才算代码，这一形状两头都不占）")
    if any("低数据2000 × α=0.3" in f for f in ph_red):
        fails.append("闸⑫（拆红模式 --bareid）把已渲染的 dict repr 仍判成残留 ⇒ 假红没修掉："
                     "『有引号就算代码』那条口径还留在判别器里，两腿没分离")
    if len(ph_red) != 1:
        fails.append(f"闸⑫（拆红模式 --bareid）这一档该恰好 1 条占位符红，现读 {len(ph_red)} 条 ⇒ "
                     "要么注入落到了别的账上，要么判别器认错了形状")

# 闸⑬：脚本"能不能打开"——每个带开关的脚本跑一次 `--help`，退出码必须是 0。
# 来历：第十八发撞到 `step5_second_teacher.py --help` **自那行帮助文本写下起就没通过过**
#   （argparse 把 help 整串做 `%` 插值，帮助文本里写 `50%` 必须写 `50%%`）。这类崩溃不在任何训练路径上，
#   而守卫是 import 模块、不走 argparse ⇒ 前十二道闸对它零反应：改了判据的崩、读档的崩都拦不到"打开就炸"。
# 这一档判的是**入口**不判读数 ⇒ 它不产生任何新的对账，也不许被读成"某句话被复证"。
# 被测清单按值现读（源码里出现 add_argument 就算），名单不写死：新加一个带开关的脚本自动进清单。
print("\n[闸⑬ 每个带开关的脚本 --help 都能打开（退出码 0）]")
HELP_SCRIPTS = [p for p in sorted(glob.glob("step*.py"))
                if "add_argument" in open(p, encoding="utf-8").read()]
PROBE = "_help_probe_v3red.py"


def _help_rc(script):
    r = subprocess.run([sys.executable, "-u", script, "--help"],
                       capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=600)
    return script, r.returncode, (r.stderr or "")


n13 = 0
_t13 = time.monotonic()
try:
    if MODE == "--helpblind":
        open(PROBE, "w", encoding="utf-8").write(
            "# -*- coding: utf-8 -*-\n"
            "import argparse\n"
            "p = argparse.ArgumentParser()\n"
            "p.add_argument('--x', help='覆盖率达到 50%、就这一句')\n"
            "p.parse_args()\n")
        print(f"  （拆红注入）生成 {PROBE}：一个只有 argparse 的合成脚本，help 串里放一个裸 % "
              "（第十八发那处崩溃的同一形状）⇒ 它必须打不开")
    targets = HELP_SCRIPTS + ([PROBE] if MODE == "--helpblind" else [])
    with ThreadPoolExecutor(max_workers=4) as ex:
        results = list(ex.map(_help_rc, targets))
    for script, rc, err in sorted(results):
        n13 += 1
        if rc != 0:
            tail = (err.strip().splitlines() or ["（无 stderr）"])[-1]
            fails.append(f"闸⑬ {script}：--help 退出码 {rc}（不是 0）⇒ 这个脚本的开关清单打不开，"
                         f"报错最后一行：{tail}")
            print(f"  {script} → **红**：rc={rc}")
    if n13 == 0:
        fails.append("闸⑬ 清单里一个带开关的脚本都没读到 ⇒ 扫描器没展开，这一档等于没测到，不许记成通过")
    else:
        green = n13 - sum(1 for f in fails if f.startswith("闸⑬"))
        print(f"  现读清单 {n13} 本（源码含 add_argument），退出码 0 的 {max(green, 0)} 本，"
              f"墙钟 {time.monotonic() - _t13:.1f} 秒（4 并发）")
    if MODE == "--helpblind":
        if not any(f.startswith("闸⑬") and PROBE in f for f in fails):
            fails.append(f"闸⑬（拆红模式 --helpblind）注入的 {PROBE} 一条都没抓到 ⇒ 这一档恒绿，"
                         "它对『帮助文本里有裸 %』零反应，拦不住下一次同类崩溃（此档等于没测到）")
        else:
            print(f"  must-catch 兑现：注入体 {PROBE} 被这一档点名（**它是合成脚本、不在那 {len(HELP_SCRIPTS)} "
                  "本真账里** ⇒ 这一档证明的是检测器会对 rc≠0 出声，不证明真账里现在有人打不开——"
                  "上面那行绿色计数说的才是真账）")
finally:
    if MODE == "--helpblind" and os.path.exists(PROBE):
        os.remove(PROBE)

# ---------- 闸⑭ 派生账的每条 CI 必须能从档案自己的 gaps 复算 ----------
# ①–⑬ 吃的是"训练路径产出的那批账"（v4f 名下）或"档案文本"（⑫）或"脚本能不能打开"（⑬）；
# 派生账（零训练、读别人的账算出来的 v4i/v4j/v4k/v4l）里那几十条 95% CI **一条都不在任何闸里**：
# 「那条跨列差 −28.1 张 CI [−42.3, −14.0]」这句话的承重是零——数字抄错一位没人出声。
# 派生账里"等价于一条步长"的那一维 = 凡带 `gaps` 的配对块（段内步长／跨列差／跨族差都是两格逐流相减），
# 所以复算单位取"一条 CI 块"而不是"一本账"：一本账里有几条就复算几条。
# 旧版豁免写成规则而不是名单：同一账族里版本号更高的本已入库 ⇒ 老本留盘只对账、不参评，
# 但豁免名单必须打印；而"最新那一本"里只要还有一条 CI 拿不出 gaps 就红 ⇒ 升版这条路拖不得。
# 专属拆红 --ciderived 两处注入各钉一条腿：改一条 CI 的上端 ⇒「复算不平」；抹掉另一条的 gaps ⇒「口径外」。
DERIVED = re.compile(r"compress_report_v4[ijkl][^/\\]*\.json$")
CI_KEYS = ("n_seeds", "mean_gap_imgs", "sd_imgs", "se_imgs", "ci95_imgs",
           "same_sign_seeds", "p_seeds_binomial", "range_imgs", "d4_sigma_hat")
CI_ALIAS = {"residual_imgs": "mean_gap_imgs", "same_sign": "same_sign_seeds",
            "p": "p_seeds_binomial"}


def _base(book):
    return book.split(chr(92))[-1]


def _famv(book):
    stem = _base(book)[: -len(".json")]
    m = re.search(r"_v(\d+)$", stem)
    return (stem[:m.start()] if m else stem, int(m.group(1)) if m else 0)


def _ci_blocks(node, path=""):
    """展开一本账里所有带 ci95_imgs 的块（连它自己的档案内路径一起交出去）。"""
    if isinstance(node, dict):
        if "ci95_imgs" in node:
            yield path, node
        for k, v in node.items():
            yield from _ci_blocks(v, f"{path}/{k}")
    elif isinstance(node, list):
        for i, v in enumerate(node):
            yield from _ci_blocks(v, f"{path}[{i}]")


d_all = sorted(b for b in arch_all if DERIVED.search(_base(b)))
_fam_top = {}
for _b in d_all:
    _f, _v = _famv(_b)
    _fam_top[_f] = max(_v, _fam_top.get(_f, -1))
d_latest = [b for b in d_all if _famv(b)[1] == _fam_top[_famv(b)[0]]]
d_old = [b for b in d_all if b not in set(d_latest)]
print(f"  派生账现读 {len(d_all)} 本：参评（各族最新版）{len(d_latest)} 本 = "
      f"{[ _base(b) for b in d_latest ]}")
print(f"  旧档豁免 {len(d_old)} 本（留盘对账、不参评）= {[ _base(b) for b in d_old ]}")

inj_recalc = inj_nogap = None
if MODE == "--ciderived":
    for b in d_latest:
        for path, blk in _ci_blocks(arch_all[b]):
            if inj_recalc is None and isinstance(blk.get("gaps"), list) and len(blk["ci95_imgs"]) == 2:
                blk["ci95_imgs"] = [blk["ci95_imgs"][0],
                                    round(float(blk["ci95_imgs"][1]) + 40.0, 1)]
                inj_recalc = f"{_base(b)}{path}"
                continue
            if inj_recalc is not None and inj_nogap is None and isinstance(blk.get("gaps"), list):
                blk.pop("gaps")
                inj_nogap = f"{_base(b)}{path}"
        if inj_nogap:
            break
    print(f"  （拆红注入）{inj_recalc or '（无可注入）'} 的 CI 上端 +40 张 ⇒ 只有复算看得见；"
          f"{inj_nogap or '（无可注入）'} 抹掉 gaps ⇒ 只有『必须有原料』那条腿看得见")
    if not (inj_recalc and inj_nogap):
        fails.append("闸⑭（拆红模式 --ciderived）两处注入凑不齐 ⇒ 至少一条腿此刻没有被测过，不许记成通过")

n14 = n14_recalc = n14_oob = 0
for b in d_latest:
    for path, blk in _ci_blocks(arch_all[b]):
        n14 += 1
        tag = f"{_base(b)}{path}"
        lo, hi = [float(x) for x in blk["ci95_imgs"]][:2]
        if not lo < hi:
            fails.append(f"闸⑭ {tag}：CI 两端不递增 {blk['ci95_imgs']} ⇒ 这条区间不是一次配对统计")
        if not isinstance(blk.get("gaps"), list):
            n14_oob += 1
            fails.append(f"闸⑭ {tag}：记了 ci95 却没有 gaps ⇒ 守卫只能照抄它，复算不了 = 口径外"
                         "（派生账的 CI 必须自带逐流原料，否则这批数字不在任何闸里）")
            continue
        n14_recalc += 1
        got = sd.summarize(list(blk["gaps"]), blk.get("label", path))
        diff = {k: (blk.get(k), got.get(k)) for k in CI_KEYS if blk.get(k) != got.get(k)}
        if diff:
            fails.append(f"闸⑭ {tag}：由档案自己的 gaps 复算与记录值不平 {diff} ⇒ 这条 CI 的十位数里"
                         "有不是从这批流算出来的")
        if len(blk["gaps"]) != blk.get("n_seeds"):
            fails.append(f"闸⑭ {tag}：len(gaps)={len(blk['gaps'])} ≠ 自报 n_seeds={blk.get('n_seeds')}"
                         " ⇒ 分母与原料不是同一批")
        for al, src in CI_ALIAS.items():
            if al in blk and src in blk and blk[al] != blk[src]:
                fails.append(f"闸⑭ {tag}：同一个数在档案里记了两处还分家（{al}={blk[al]} vs {src}={blk[src]}）")
if n14 == 0:
    fails.append("闸⑭ 一条派生账 CI 都没读到——不是通过，是没测到（glob 空转或派生账被改名）")
else:
    print(f"  现读 {n14} 条 ci95：可复算 {n14_recalc} 条（逐字段命中）、口径外 {n14_oob} 条")
if MODE == "--ciderived":
    if inj_recalc and not any(f.startswith("闸⑭") and inj_recalc in f and "复算" in f for f in fails):
        fails.append(f"闸⑭（拆红模式 --ciderived）改了 CI 端点却没抓到（{inj_recalc}）⇒ 复算那条腿恒绿")
    if inj_nogap and not any(f.startswith("闸⑭") and inj_nogap in f and "口径外" in f for f in fails):
        fails.append(f"闸⑭（拆红模式 --ciderived）抹掉 gaps 却没抓到（{inj_nogap}）⇒ 『必须有原料』那条腿恒绿")

# ---------- ⑮ 债句指针（第二十八发：把上一发记成"新欠"的那根会漂的指针变成守卫） ----------
# 形状：档案里「<某本账>.json 的 limitations 第 N 条（『引文』…）」——文件名 + 序号 + 引文三件套齐了才算**可核指针**。
# 判据：引文按 `…` 切成片段，每个片段都必须躺在那本账 `limitations[N-1]` 里；不在就红，并把"按内容命中的是第几条"打出来。
# 为什么值得常驻：`limitations` 每一版都在**头部**插一条变更说明 ⇒ 同一句话的序号每升一版 +1
# （现读 v4i 那本：债句在 v1/v2/v3 = 第 2/3/4 条），所以"写死序号"是一根会自己漂走的指针。
# 只写了"第 N 条"却没点名的那类（裸序号引用）不猜目标，只数出来报分母——猜目标等于把判别器建在假设上。
PTR_FORM = re.compile(r"(compress_report_[A-Za-z0-9_]+\.json)\s*的\s*limitations\s*第\s*(\d+)\s*条[^。；]{0,4}『(.+?)』")
PTR_BARE = re.compile(r"limitations[^。；]{0,14}第\s*\d+\s*条")
NEWEST = {}
for _b in sorted(arch_all):
    _f, _v = _famv(_b)
    if _f not in NEWEST or _v > NEWEST[_f][0]:
        NEWEST[_f] = (_v, _b)
# 参评口径（第廿九发，与闸⑭ 同一条规矩）：**指针的出处**只取每族最高版，旧版留盘豁免。
# 为什么这一条必须由代码持有而不是留在散文里：v4j 那句"转述冒充引用"在 v2 里已经改成逐字了，
# 可 v1 还在盘上（留盘对账是板块规矩），全册扫描就让那一桶永远降不回 0 ⇒ 付了 46 次训练换不来一格变绿，
# 而且下一次升版会把"已还的债"重新记成"在册缺陷"。**目标那一侧仍按全册查**：指针写的是哪本就叫哪本，
# 指到已被取代的旧版正是"过期指针"这一桶的原料，把它从扫描面里删掉等于把桶底凿穿。
_p_top = {}
for _b in sorted(arch_all):
    _f, _v = _famv(_b)
    _p_top[_f] = max(_v, _p_top.get(_f, -1))
P_LATEST = {b for b in arch_all if _famv(b)[1] == _p_top[_famv(b)[0]]}
P_OLD = sorted(set(arch_all) - P_LATEST)


def _ptr_tag(book, path, tgt, n):
    """一条指针的身份证。守卫的红句与 --limitptr 的各腿共用这一个构造：
    拆红腿要靠它认出『哪几条红是我刚注入那一条』，两处各写一遍格式就会静默对不上。"""
    return f"{_base(book)}{path} → {_base(tgt)} 第 {n} 条"


def _ptr_scan(books, src=None):
    """纯函数：抽**参评那批账**里的可核指针 → 逐条按内容核。

    `src` 是出处的扫描面（默认全给）；调用方传 `P_LATEST` 就是"每族最高版参评、旧版豁免"。
    目标一律在 `books`（全册）里查，理由见上面那段。

    返回 (指针清单, 裸序号引用条数, 红清单, 过期指针清单, 引文不逐字清单)。
    红只给本闸广告过的那件事：**指针会漂**（序号与内容命中位置分家 / 被指那本不在盘上）。
    另两类只出声——它们的修法都要重跑付费档案（见文件头 ⑮ 那一段）。"""
    named, bare, out, stale, noquote = [], 0, [], [], []
    for book, d in sorted(books.items()):
        if src is not None and book not in src:
            continue
        for path, s in _walk(d):
            hits = list(PTR_FORM.finditer(s))
            bare += max(0, len(PTR_BARE.findall(s)) - len(hits))
            for m in hits:
                tgt, n, frag = m.group(1), int(m.group(2)), m.group(3)
                named.append((book, path, tgt, n))
                tag = _ptr_tag(book, path, tgt, n)
                if tgt not in books:
                    out.append(f"闸⑮ {tag}：被指的那本账不在盘上 ⇒ 这条指针悬空，谁都不能核它")
                    continue
                lims = books[tgt].get("limitations") or []
                if _famv(tgt)[1] < NEWEST[_famv(tgt)[0]][0]:
                    # 它指的那本已被同族新版取代。放在逐字判定**之前**算：这两件事互相独立，
                    # 若排在后面，那条引文不逐字的指针会先 continue 掉，这一桶就恒等于 0（报 0 不算测过）
                    stale.append(tag)
                pieces = [p.strip() for p in re.split(r"…|\.\.\.", frag) if p.strip()]
                moved = [i + 1 for i, x in enumerate(lims) if pieces and all(p in str(x) for p in pieces)]
                if not moved:
                    noquote.append(f"{tag}（引文『{frag}』在那本账 {len(lims)} 条里逐字命中 0 条）")
                    continue
                if n not in moved:
                    out.append(f"闸⑮ {tag}：那句引文按内容命中的是第 {moved} 条而不是第 {n} 条"
                               f"（那本账共 {len(lims)} 条）⇒ `limitations` 每升一版就在头部插一条变更说明，"
                               "写死的序号会静默漂走")
                    continue
    return named, bare, out, stale, noquote


def _ptr_toks(path):
    """`.gaps[2].note` → ['gaps', 2, 'note']：`_walk` 的路径不是字典键，读写都得先拆。"""
    toks = []
    for part in path.split(".")[1:]:
        head = part.partition("[")[0]
        if head:
            toks.append(head)
        for i in re.findall(r"\[(\d+)\]", part):
            toks.append(int(i))
    return toks


def _ptr_get(books, book, path):
    node = books[book]
    for t in _ptr_toks(path):
        node = node[t]
    return node


def _ptr_patch(books, book, path, value):
    """把 `_walk` 吐出来的路径写回 books[book]——注入腿要靠它改嵌套字段。"""
    toks = _ptr_toks(path)
    node = books[book]
    for t in toks[:-1]:
        node = node[t]
    node[toks[-1]] = value


if MODE == "--limitptr":
    import copy as _copy
    probe, _, ptr0, stale0, nq0 = _ptr_scan(arch_all, P_LATEST)
    print(f"  参评出处 = 每族最高版 {len(P_LATEST)} 本（全册 {len(arch_all)} 本）；"
          f"旧档豁免 {len(P_OLD)} 本 = {[_base(b) for b in P_OLD]}")
    if not probe:
        fails.append("闸⑮（拆红模式 --limitptr）参评那批账里没有一条可核指针可注入 ⇒ 各腿此刻全是空转，不许记成通过")
    else:
        bk, pth, tgt_book, _n = probe[0]

        def _quote_with(s, new_frag):
            return PTR_FORM.sub(lambda m: m.group(0).replace(f"『{m.group(3)}』", f"『{new_frag}』"), s)

        def _bump(s, delta):
            return PTR_FORM.sub(lambda m: m.group(0).replace(f"第 {m.group(2)} 条",
                                                             f"第 {int(m.group(2)) + delta} 条"), s)

        def _retarget(s, new_name):
            return PTR_FORM.sub(lambda m: m.group(0).replace(m.group(1), new_name), s)

        base = _copy.deepcopy(arch_all)
        orig = _ptr_get(base, bk, pth)
        frag0 = list(PTR_FORM.finditer(orig))[0].group(3)
        bad = frag0 + "（拆红注入：尾巴上多这一段，盘上没有任何账这么说）"
        # ---- 腿 E（第廿九发改道：底座不再靠盘上真缺陷）----
        # 上一版这条腿断言『全册 ≥1 条引文不逐字』，靶子就是 v4j v1 那句转述冒充引用。B 把它修成逐字之后，
        # 这条断言会**因为债被还清而红**——常驻判别器把靶子建在"现网恰好坏着"上，等于给自己安排一次报废。
        # 现在坏法由注入造，并且两向都量（0→1、再回到 0），量的是"这条计数会跟着坏法动"，不是"现网是坏的"。
        if len(nq0) or len(ptr0):
            print(f"  ⚠ 参评现读底座不是 0 / 0（不逐字 {len(nq0)}、红 {len(ptr0)}）⇒ 盘上又冒出新坏法："
                  f"注入腿照跑，但那一格先按在册缺陷读，不许顺口说『守卫全绿』")
        mut_e = _copy.deepcopy(base)
        _ptr_patch(mut_e, bk, pth, _quote_with(orig, bad))
        _, _, rE, _, nqE = _ptr_scan(mut_e, P_LATEST)
        mut_e2 = _copy.deepcopy(mut_e)                       # 反向：把引文逐字贴回去 ⇒ 桶必须降回原样
        _ptr_patch(mut_e2, bk, pth, _quote_with(_ptr_get(mut_e2, bk, pth), frag0))
        _, _, rE2, _, nqE2 = _ptr_scan(mut_e2, P_LATEST)
        print(f"  腿 E（注入）：不逐字 {len(nq0)} → {len(nqE)} → 复跑 {len(nqE2)} 条；"
              f"红 {len(ptr0)} → {len(rE)} → {len(rE2)} 条")
        if len(nqE) != len(nq0) + 1:
            fails.append(f"闸⑮（--limitptr 腿E）把引文改坏之后不逐字计数 = {len(nqE)}（要 {len(nq0)} + 1）"
                         "⇒ 『必须有原料』这条计数不承重，报 0 不算测过")
        if len(nqE2) != len(nq0) or len(rE2) != len(ptr0):
            fails.append(f"闸⑮（--limitptr 腿E 反向）把引文贴回逐字之后不逐字 = {len(nqE2)}、红 = {len(rE2)}"
                         f"（要 {len(nq0)} / {len(ptr0)}）⇒ 这条腿只会单向报警，分不清『我改坏了夹具』与『现网坏了』")
        if len(rE) != len(ptr0):
            fails.append(f"闸⑮（--limitptr 腿E）引文不逐字应当只进『不逐字』那一桶（出声不红），"
                         f"实测红 {len(rE)} 条（底座 {len(ptr0)}）⇒ 两桶混成一条，改天真要报漂移红就分不清是谁")
        # ---- 腿 D（第廿九发新增）：『过期』与『不逐字』是两桶，判定顺序不许让前一只吞掉后一只 ----
        # 第廿八发把过期判定挪到逐字判定**之前**，理由是挪在后面那一桶会结构性恒 0（报 0 不算测过）。
        # 当时没有一档会因为这件事红 ⇒ 那条修法只是我说的。这一腿就是它的凭据：先造"只过期、仍逐字"，
        # 再在它之上把引文改坏，要求两桶**同时**非零。造不出靶子就登记死闸，不许不跑就当通过。
        older = [b for b in P_OLD if _famv(b)[0] == _famv(tgt_book)[0]]
        if not older:
            print(f"  腿 D：盘上没有 {tgt_book} 的旧版 ⇒ 『指针指向旧版』这一格造不出来（**死闸**，登记不记通过）")
        else:
            tgt_old = max(older, key=lambda b: _famv(b)[1])
            lims_old = arch_all[tgt_old].get("limitations") or []
            pieces = [p.strip() for p in re.split(r"…|\.\.\.", frag0) if p.strip()]
            moved_old = [i + 1 for i, x in enumerate(lims_old) if pieces and all(p in str(x) for p in pieces)]
            if len(moved_old) != 1:
                print(f"  腿 D：那句引文在旧版 {tgt_old} 里按内容命中 {moved_old} 条（要恰好 1）"
                      f"⇒ 造不出『只过期、仍逐字』的靶子（**死闸**，不许改判据凑靶子）")
            else:
                d1_str = _bump(_retarget(orig, tgt_old), moved_old[0] - _n)   # 只改指向 + 序号按旧版算对
                mut_d1 = _copy.deepcopy(base)
                _ptr_patch(mut_d1, bk, pth, d1_str)
                _, _, rd1, sd1, nd1 = _ptr_scan(mut_d1, P_LATEST)
                mut_d2 = _copy.deepcopy(mut_d1)
                _ptr_patch(mut_d2, bk, pth, _quote_with(_ptr_get(mut_d2, bk, pth), bad))
                _, _, rd2, sd2, nd2 = _ptr_scan(mut_d2, P_LATEST)
                print(f"  腿 D：指向 {tgt_old}（那句在它那里是第 {moved_old[0]} 条）⇒ 过期 {len(stale0)} → {len(sd1)} 条、"
                      f"不逐字 {len(nq0)} → {len(nd1)} 条、红 {len(ptr0)} → {len(rd1)} 条；"
                      f"在它之上再改坏引文 ⇒ 过期 {len(sd2)} 条、不逐字 {len(nd2)} 条")
                if not (len(sd1) > len(stale0) and len(nd1) == len(nq0) and len(rd1) == len(ptr0)):
                    fails.append(f"闸⑮（--limitptr 腿D1）『只过期、仍逐字』应当只让过期那一桶动，实测 "
                                 f"过期 {len(stale0)}→{len(sd1)}、不逐字 {len(nq0)}→{len(nd1)}、红 {len(ptr0)}→{len(rd1)}"
                                 " ⇒ 这一桶与逐字判定分了家，谁漂了都说不清")
                if not (len(sd2) >= 1 and len(nd2) > len(nq0)):
                    fails.append(f"闸⑮（--limitptr 腿D2）过期 + 不逐字同时在场时读到 过期 {len(sd2)} 条、"
                                 f"不逐字 {len(nd2)} 条 ⇒ 『过期先判』把后一桶吞了（第廿八发那条修法的原病，红要报 0 就不算测过）")
        # ---- 在这个可核底座上测三条漂移腿 ----
        # 口径（第廿九发改）：断言一律写成"**相对底座的增量**"，不写绝对红数。
        # 上一版写的是"恰好 1 红 / 恰好 0 条指针"，那句话隐含的前提是"全册只有一条指针"——
        # 而 B、C 两发之后参评集合里有了**两条同形指针指同一本同一格**
        # （`v4j_matched_n8_v2` 与 `v4j_matched_n16` 的 `pays` 都指向 `v4i_mechanism_v3` 第 4 条）。
        # 于是：头部插一条会**如实地**把两条都判红（它们各自都漂了），
        #       把其中一条改成内容式会**如实地**留下另一条。绝对口径把这两件正确的事读成不承重。
        # 增量口径在只有一条指针时退化成"恰好 1"，两条时退化成"恰好 2"，都不需要再改代码。
        now = _ptr_get(base, bk, pth)
        red_tag0 = {x.partition("：")[0] for x in ptr0}
        at_tgt = [e for e in probe if e[2] == tgt_book]
        clean_at_tgt = [e for e in at_tgt if _ptr_tag(*e) not in red_tag0]
        mut_a = _copy.deepcopy(base)
        _ptr_patch(mut_a, bk, pth, _bump(now, 1))                      # 腿 A：序号 +1，内容一个字没动
        mut_b = _copy.deepcopy(base)
        mut_b[tgt_book]["limitations"].insert(                          # 腿 B：被指那本头部插一条 = 真升版的形状
            0, "（拆红注入）这一条插在最前面，模拟 limitations 每升一版在头部加一条变更说明")
        mut_c = _copy.deepcopy(base)
        # 反对照 = 把指向同一本的指针**全部**改成内容式引用（正确的修法要一次修干净；
        # 只改 probe[0] 会让"同座标那条"还留在清单里，那测的是漏改，不是正确修法）
        for e in at_tgt:
            s = _ptr_get(mut_c, e[0], e[1])
            _ptr_patch(mut_c, e[0], e[1], PTR_FORM.sub(
                lambda m: m.group(0).replace(f"第 {m.group(2)} 条", "里那句"), s))
        pa, _, ra, _, _ = _ptr_scan(mut_a, P_LATEST)
        pb, _, rb, _, _ = _ptr_scan(mut_b, P_LATEST)
        pc, _, rc, _, _ = _ptr_scan(mut_c, P_LATEST)
        want_a = len(ptr0) + 1                    # 只有被 +1 的那一条漂；同座标那条一个字没动
        want_b = len(ptr0) + len(clean_at_tgt)    # 指向同一本的那几条**全部**会漂，这是真升版的形状
        want_c = len(probe) - len(at_tgt)         # 该本的指针全改成内容式 ⇒ 从指针清单里整体消失

        def _red_with(reds, tag):
            """按身份证取那一句红，不按位置切：_ptr_scan 按账名排序，底座红与新红谁在前是盘上顺序决定的。"""
            return [x for x in reds if x.partition("：")[0] == f"闸⑮ {tag}"]

        def _cred(leg, red):
            """凭据那句红的开头必须仍是 `闸⑮`：本轮逐档红数按『以闸字开头的失败行』计数，
            把归属括号放在开头会让一条真红静默计成 0（拆红档报了 0 与没跑同形）。"""
            return f"闸⑮（--limitptr 腿{leg} 注入的凭据）{red.split('闸⑮ ', 1)[1]}"

        print(f"  底座：参评可核指针 {len(probe)} 条，其中指向 {tgt_book} 的 {len(at_tgt)} 条"
              f"（现在干净的 {len(clean_at_tgt)} 条）⇒『同一格住几条』由盘上现读决定，不写死"
              + ("；同形多条 = B/C 两发各入库一本而 `pays` 是同一句代码写的" if len(at_tgt) > 1 else ""))
        print(f"  腿 A 序号 +1：指针 {len(pa)} 条 / 红 {len(ra)} 条（要 {want_a}）；"
              f"腿 B 头部插一条：{len(pb)} 条 / 红 {len(rb)} 条（要 {want_b}）；"
              f"腿 C 改成内容式：{len(pc)} 条（要 {want_c}）/ 红 {len(rc)} 条（要 {len(ptr0)}）")
        hit_a = _red_with(ra, _ptr_tag(bk, pth, tgt_book, _n + 1))
        if len(ra) == want_a and len(hit_a) == 1:
            fails.append(_cred("A", hit_a[0]))
        else:
            fails.append(f"闸⑮（--limitptr 腿A）序号 +1 之后红 {len(ra)} 条（要 {want_a} 条，底座 {len(ptr0)} 条"
                         f"+ 被注入那 1 条）且红的身份要正好是 {_ptr_tag(bk, pth, tgt_book, _n + 1)}，实测命中 {len(hit_a)} 条"
                         "⇒ 『序号与内容分家』这条腿不承重，或者它红在了别处")
        # 腿 B 的红身份用**原序号**：这一腿改的是被指那本，指针文本一个字没动（与腿 A 相反）
        missing_b = [e for e in clean_at_tgt if f"闸⑮ {_ptr_tag(*e)}" not in {x.partition("：")[0] for x in rb}]
        cred_b = _red_with(rb, _ptr_tag(*clean_at_tgt[0])) if clean_at_tgt else []
        if len(rb) == want_b and len(set(x.partition("：")[0] for x in rb)) == len(rb) \
                and not missing_b and len(cred_b) == 1:
            fails.append(_cred("B", cred_b[0]))
        else:
            fails.append(f"闸⑮（--limitptr 腿B）被指那本头部插一条之后红 {len(rb)} 条（要 {want_b} 条，"
                         f"= 底座 {len(ptr0)} + 指向它的干净指针 {len(clean_at_tgt)} 条），"
                         f"且每条红指不同出处、点名点得到（点不到的：{[_ptr_tag(*e) for e in missing_b] or '无'}，"
                         f"凭据那一格命中 {len(cred_b)} 条）⇒ "
                         "『世界漂了而指针没跟着漂』这条腿不承重")
        if len(pc) != want_c or len(rc) != len(ptr0):
            fails.append(f"闸⑮（--limitptr 腿C 反对照）把指向 {tgt_book} 的 {len(at_tgt)} 条指针改成内容式引用之后"
                         f"仍读到 {len(pc)} 条指针（要 {want_c}）/ 红 {len(rc)} 条（要 {len(ptr0)}）"
                         "⇒ 判别器在惩罚正确的修法，会把人推回写死序号")

named_ptr, bare_ptr, ptr_red, stale_ptr, nq_ptr = _ptr_scan(arch_all, P_LATEST)
fails.extend(ptr_red)
if MODE != "--limitptr":
    if not named_ptr:
        fails.append("闸⑮ 全册一条可核指针都没读到 ⇒ 不是通过，是没测到（glob 空转，或指针换了形状而这条闸看不见）")
    else:
        print(f"  现读可核指针 {len(named_ptr)} 条（出处参评 {len(P_LATEST)} 本 = 每族最高版，"
              f"旧版豁免 {len(P_OLD)} 本）：漂走 {len(ptr_red)} 条、裸序号引用 {bare_ptr} 条；"
              f"只出声的两类 = 引文不逐字 {len(nq_ptr)} 条、过期指针 {len(stale_ptr)} 条（都不红，理由见文件头 ⑮）")
        for x in nq_ptr:
            print(f"    · 引文不逐字：{x}")
        for x in stale_ptr:
            print(f"    · 过期指针：{x}")


# ════════════════════════════════════════════════════════════════════════════
# 闸⑯ 正文引用的"库外一次性件"必须自带声明（第卅发新增·零训练）
# ════════════════════════════════════════════════════════════════════════════
# 口径（三句话，写在这条闸旁边是因为它得能被现读复算）：
#   ① 参评引用面 = 本模块**在册**的 .py/.md + 根目录那两本会引用它的文档（别的项目模块不在射程里）；
#   ② 名字**只从引用面正文里现读**：凡用反引号写成**整名**、且形状是"能落到盘上的路径"——以已知
#      扩展名结尾（`_CIT_EXT` 那张表：.log/.py/.json/.md/.pt/.onnx/…）或以 `/` 结尾的目录写法——
#      而它**不是任何全仓在册路径的尾段**、也不是任何在册路径的目录前缀 ⇒ 判为断链指针；每一次提到
#      它，±2 行内必须有一行**同时含这个名字和一个声明词**（点名式声明）。
#      形状这一条是第卅一发现读补的：第卅发那句"下划线开头或以 .log 结尾"太宽，直接套会把 447 处
#      `_n8`/`_v4`/`_ptr_tag` 这类**尾段简写**和别的模块的在册件（`ask.py`）读成断链——实测 56 处假红。
#   ③ 点不到名 ⇒ 红。判的是"clone 之后这句话还成不成立"，不是"此刻这台机器上有没有那个文件"。
# 为什么要一条闸而不是又一轮人肉搬：同一件事三发里坏了三次——第廿八发记下、第廿九发结掉一半的
# 新欠⑶（本文件里那三处 _tmp_redNN 日志）、本轮菜单 B 搬掉的三处、**装这条闸时现读又抓到的一处**
# （第廿二发那条"第一次跑 8 条流被杀"的墙钟原件）。每一次写的人都是诚实的：他当时看得见那个文件。
# 会说谎的是"盘上"这两个字，不是人——所以这条闸管的是措辞欠下的义务，不是文件的存在。
# 〔第卅一发收紧两处，都是先量后改〕
# 一、名字来源从「盘上现读 ∪ 手写登记处 SCRATCH_CITED」换成**纯正文现读**。原先那句"只扫盘 ⇒
#     清理之后裸引用永远查不红"站不住：裸引用里那个名字本来就是正文给的，`os.listdir` 那一半从来
#     不是必要条件，它只让**分母跟着这台机器的目录漂**（第卅发同一轮两次裸跑之间名字数 100→108）。
#     登记处那一半则是第卅发明记的新欠——下一发新造的名字没人补它。两个来源换成一个来源，
#     漂移和衰减**同时**结掉。如实记下丢掉的那一半覆盖：不带反引号写出来的名字不在射程里，
#     这条闸认的是"反引号整名"这个书写约定，不是"一切指向库外的措辞"。
# 二、声明判定从「±2 行内出现标记词」收紧成「±2 行内有一行同时含**这个名字**和标记词」（点名式）。
#     旧口径留着一个自我消音的口子：正文里任何一句写了"本机/库外/清理清单"的话——哪怕说的是别的
#     文件——都会替旁边那条真断链作保。收紧前先在盘上量了三种口径（`_tmp_r31_legprobe.py`，一次性件）：
#     ±2 行 55 带声明 / 0 裸；同行 46 / 9；点名式 46 / 9，且**后两档判红的集合完全相同**（两个差集都
#     是空）⇒ 那 9 处不是假红，是措辞确实没点名的债。**但"9"是收紧前那一次测量的数，不能拿来当整改
#     清单**：形状判据（上一条②）落地之后，同一句正文现读出的裸引用是 **24 处**，那 9 处只是它的子集。
# 三、24 处的处置与"收益"（第卅一发菜单 B：24 处**全部改正文**，另外给声明词表加了两个词，加完当场量了它承重多少）：
#        词表从 HEAD 版的十个词加到十二个（新增 `不入库|已删除`）。加词不是免费的，所以收口时跑了
#        一次两遍对照（把 `_LOCAL_MARK` 临时换回 HEAD 版、原样重跑 `normal`、再逐字节还原）：
#        **HEAD 词表下 ⑯ 报 14 条裸引用，现词表下 0 条** ⇒ 那两词替 14 处作了保，是承重的。
#        那 14 处逐条抄出来核过：每一句都写着"不入库""此件不入库""账已删除""验完即删、不入库"
#        这一类真声明（`_tmp_r31_markdiff.txt`，本机、不入库）⇒ 判读是**词表认不出同义词**（旧表有
#        `不在库里`/`库外` 却没有 `不入库`），不是把假话说绿。但这条账必须登记：**加词让 14 处变绿，
#        而守卫里没有任何一档会因"词表被加宽"而红**——第卅发新欠⑸ 预言的正是这个失效模式，本轮
#        由我自己兑现了一次。
#     ① 措辞没点名 → 把声明写成点名的（`summary.txt` 与 `_qq.py` 都是本机一次性件、已删除，
#        `step4l` 那两本改名件不入库，`data/fashion/` 那一行改成点名"不在库里"）；
#        ② **实质假话** → 六处把 `models/*.pt` 写成"已入库/在盘"，现读
#        `git ls-files` 全仓在册 `.pt` = **0 本**、`models/` 是 `ml-compress/.gitignore` 第一行，那六个
#        字是假的，不是欠一个标记词 ⇒ 改成本机 + 不入库 + 可复现命令（`train_baseline.py` /
#        `step5_second_teacher.py --teacher B|C` / `step6_fashion_replication.py`）；那种"绿"若靠加
#        词表换来，闸就等于被整改对象改写了。整改后 normal rc=0 / 0 红。
#     ③ **本闸的已知盲区，由腿G 量着而不是靠这句话自认**：点名式只要求"名字与声明词**同现于一行**"，
#        管不了那个词是不是在说这个名字——README:1158 就是活例（那行的"本机"修饰的是"同期本机有 21 个
#        并存的 python 进程"，跟那本日志无关，却让这句引用合法变绿）。腿G 注入的就是这个形状，
#        期望 0 红（盲区成立）；哪天判据严到能红了，腿G 会反过来红着要求把这段话改写。
# 词表哨兵（第卅二发·结第卅一发新欠⑵）：一句**真声明**用的词，但它**不在**上面那张表里。
# 为什么需要它：上一发整改 24 处裸引用时我给词表加了两个词，加完量出"那两个词替 14 处作了保"——
# 可是**守卫里没有任何一档会因为『词表被加宽』而红**，也就是说下一次加词可以悄无声息地发生。
# 这条哨兵把"加词"变成一件必须留痕的事：把它收进词表 ⇒ 下面那条常驻红立刻点名（在 normal 与每一档都跑）。
# 想加词的人必须同时改这个常量，而那在 diff 里是一行藏不住的话——就像腿E 之于"换行位置承重"。
_SENTINEL_MARK = "用完即删"
_LOCAL_MARK = re.compile(r"本机|不在库里|库外|不入库|已删除|gitignore|断链|作废|叙述级|清理清单|一次性件|永久保留")
_nmark16 = len(_LOCAL_MARK.pattern.split("|"))   # 词数现读：加词/删词都会改这个数，文案不写死
# 句界（第卅八发 E）：只认句终符 。！？ 与半／全角分号。**逗号、冒号、顿号故意不算**——算了就把
# "同段写明"变成"紧邻声明"，同一句里的补语也会被切开（第卅八发量过：软句口径把 9 处抬到 51 处）。
_SENT_BREAK = re.compile("[。！？;；]")
_BT_TOKEN = re.compile(r"`([^`\s]{3,})`")
_ROOT_DOCS = ("../README.md", "../项目复盘与简历写法.md")


def _git_tracked(extra=(), use_dot=True):
    """在册名单。cwd 恒为本模块目录，所以模块内是相对名、根目录那两本带 ../。
    `.` 是承重的：少了它，git 把 pathspec 当**过滤**用 ⇒ 名单塌成那两本，本模块所有在册件
    （含 `_red_v3.py` 自己、`_coef_check.py`）都会被误判成"库外断链"。第卅发就是这么坏的。"""
    return [x for x in subprocess.run(
        ["git", "-c", "core.quotepath=false", "ls-files"] + (["."] if use_dot else []) + list(extra),
        capture_output=True, text=True, encoding="utf-8").stdout.splitlines() if x]


def _git_repo_paths():
    """**全仓**在册路径，且按仓库根写。两个坑都是第卅一发现读抓到的：
      ① pathspec 必须写 `:/`——`git ls-files` 不带参数只列当前子目录（本目录实测 145 本 vs 全仓 326 本），
         拿它当分母会把别的模块的在册件（`ask.py`、`scripts/cloud_probe.py`）读成库外断链；
      ② 必须加 `--full-name`——不带它时 `:/` 返回的是相对 cwd 的 ../ml-compress/README.md 那种形态，
         而正文按仓库根写 `ml-compress/README.md`，尾段判据对不上 ⇒ 在册件照样被点名。"""
    return [x for x in subprocess.run(
        ["git", "-c", "core.quotepath=false", "ls-files", "--full-name", ":/"],
        capture_output=True, text=True, encoding="utf-8").stdout.splitlines() if x]


CIT_TRACKED = _git_tracked(_ROOT_DOCS)
CIT_NAMES = {p.rsplit("/", 1)[-1] for p in CIT_TRACKED}
CIT_REPO = _git_repo_paths()

_CIT_EXT = re.compile(r"\.(?:log|py|json|md|txt|pt|pth|onnx|csv|tsv|html|bat|sh|yml|yaml|ini|lock|xml)$")


def _scratch_pointer(tok, repo_paths):
    """这个反引号整名是不是一次性件的指针。四条都过才算：
      ① 不是 glob／省略写法（`compress_report_v4f*.json`、`..._n8_v4.json` 指向的是账族，不是某个原件）；
      ② 形状是**完整**件名：以已知扩展名结尾，或以 `/` 结尾；这条挡掉 447 处 `_n8`/`_v4`/`_ptr_tag`
         那类尾段简写与标识符（它们不是路径）；
      ③ 不是任何全仓在册路径的**尾段**：一处判据同时挡掉在册件本身（`_red_v3.py`）、它的相对写法
         （`scripts/cloud_probe.py`）和在册账名的尾段（`_fashion.json` 是
         `compress_report_v6_fashion.json` 的尾巴）；
      ④ 目录写法（`ml-compress/`）若命中任何在册路径的**目录前缀** ⇒ clone 之后那个目录在，不算断链；
         落空的留在射程里——比如 `data/fashion/`（本机一次性件、运行时下载的数据集目录）。"""
    if "*" in tok or "?" in tok or tok.startswith("..."):
        return False
    if _CIT_EXT.search(tok):
        return not any(p.endswith(tok) for p in repo_paths)
    if tok.endswith("/"):
        seg = tok.rstrip("/")
        return not any(p.startswith(seg + "/") or ("/" + seg + "/") in p or p.endswith("/" + seg + "/")
                       for p in repo_paths)
    return False


def cited_surfaces(tracked=None):
    """引用面只收**在册**文件：草稿引草稿不是断链（第廿九发 F 清点踩过的第二个坑）。"""
    tracked = CIT_TRACKED if tracked is None else tracked
    cands = sorted(glob.glob("*.py") + glob.glob("*.md")) + list(_ROOT_DOCS)
    return {p: open(p, encoding="utf-8").read().splitlines()
            for p in cands if p in tracked and os.path.isfile(p)}


def cited_denominator_ok(tracked):
    """分母自证：在册名单必须收得下本模块自己（`_red_v3.py` 在册且以 `_` 开头，是最省事的探针）。
    名单一旦塌成引用面那两本，这条闸会把满目录的在册件当断链点名——那种红看着像正文的债，其实是分母坏了。"""
    return "_red_v3.py" in {p.rsplit("/", 1)[-1] for p in tracked} and len(tracked) > 20


def cited_universe(surfaces, repo_paths=None):
    """(每个库外一次性件指针 → 它被提到的地方, 指针种类数)。
    名字只有这一个来源：正文里的反引号整名。不扫盘、不靠手写登记处——第卅一发起这是口径的一部分。"""
    repo_paths = CIT_REPO if repo_paths is None else repo_paths
    hits = {}
    for path, ls in surfaces.items():
        for i, line in enumerate(ls, 1):
            for m in _BT_TOKEN.finditer(line):
                tok = m.group(1)
                if _scratch_pointer(tok, repo_paths):
                    hits.setdefault(tok, []).append((path, i))
    return hits, len(hits)


def _sent_of(joined, off):
    """偏移 `off` 落在哪一句里（句界只认 。！？ 与半／全角分号；逗号冒号不算，
    否则判据就从『同段』滑成『紧邻』——第卅八发 E 量过那一档：软句会把 9 处抬成 51 处）。"""
    pos = 0
    for s in _SENT_BREAK.split(joined):
        if pos <= off < pos + len(s):
            return s
        pos += len(s) + 1
    return ""


def _cited_pass(surfaces, hits, strip_win, unit):
    """两遍判定的**同一个**循环，只有"救回"的单位不同：
      unit=`row`      甲＝第卅一发起的旧单位，窗口里有一整**物理行**同时含名字与声明词；
      unit=`sentence` 戊＝第卅八发 E 采用的单位，窗口仍以 ±2 行为**段**（行与行以空格相接，
                      所以跨行的一句不会被行尾切开），但点名与声明必须落在**同一句**里。
    为什么整行不够：引用面的**物理行**长度由闸⑯ 后面那条常驻读数现读（第卅八发 E 量到时中位 180、
    p90 5330、最长 32007 字符）——README 的『一整发写进行』落地段就属于后者，在那种行上
    『同一物理行』＝『同一文档』，整行单位等于没判。"""
    bare, saved = [], []
    for nm, where in hits.items():
        for path, ln in where:
            if path not in surfaces:
                continue
            lines = list(surfaces[path])
            lo, hi = max(0, ln - 3), min(len(lines), ln + 2)
            if strip_win == (path, ln):
                for j in range(lo, hi):
                    lines[j] = _LOCAL_MARK.sub("", lines[j])
            if unit == "row":
                ok = any(nm in x and _LOCAL_MARK.search(x) for x in lines[lo:hi])
            else:
                line = lines[ln - 1] if ln - 1 < len(lines) else ""
                joined = " ".join(lines[lo:hi])
                base = sum(len(lines[j]) + 1 for j in range(lo, ln - 1))
                ok = any(_LOCAL_MARK.search(_sent_of(joined, base + m.start()))
                         for m in re.finditer(re.escape(nm), line))
            (saved if ok else bare).append((nm, path, ln))
    return sorted(bare), sorted(saved)


def cited_scan(surfaces, hits, strip_win=None):
    """返回 (裸引用, 被声明救回)。判定＝点名式**且段内同句**（戊）：±2 行的段里，
    含这个名字的那一句必须同时含一个声明词。旧口径（整行）只要那一行里名字与声明词共现就放行
    ⇒ 正文里任何一句"本机/库外/清理清单"——哪怕它说的是别的文件、哪怕它在七千字符之外——
    都会替旁边那条真断链作保（自我消音）。strip_win=(文件, 行号) 只改内存里那一处的窗口。"""
    return _cited_pass(surfaces, hits, strip_win, "sentence")


def cited_scan_row(surfaces, hits, strip_win=None):
    """甲（整行单位）的同一遍扫描。**不作判据**，只用来现读"把判定单位从行收到句"这一步
    到底改变了多少处——那个差额就是本轮还的债的面，也是 `--longline` 的专属校验目标。"""
    return _cited_pass(surfaces, hits, strip_win, "row")


_T16 = time.perf_counter()
CIT_SURF = cited_surfaces()
CIT_HITS, CIT_SCOPE = cited_universe(CIT_SURF)
CIT_BARE, CIT_SAVED = cited_scan(CIT_SURF, CIT_HITS)
CIT_ROW_BARE, CIT_ROW_SAVED = cited_scan_row(CIT_SURF, CIT_HITS)
_T16C = time.perf_counter() - _T16
print("\n[闸⑯ 正文用反引号引用的库外一次性件，每一次提到都要在同段**内含名字那一句**写明它不在库里]")
print(f"  引用面 {len(CIT_SURF)} 个在册文件（在册名单 {len(CIT_TRACKED)} 本）；名字由正文现读 {CIT_SCOPE} 个"
      f"（不扫盘、不靠登记处）；命中引用 "
      f"{sum(len(v) for v in CIT_HITS.values())} 处 = 点名式带声明 {len(CIT_SAVED)} + 裸引用 {len(CIT_BARE)}"
      f"（只有裸的算红）；本闸墙钟 {_T16C:.2f} 秒")
# 常驻·长行暴露面（第卅八发 E 还新欠⑸）：判据从『整行』收到『段内同句』，这一步**在本轮正文面上**
# 改变多少处，必须由这两个单位各扫一遍现读，不许引用第卅七发那个"0 条裸引用"——那个 0 是整行单位下的 0。
_hitlens = sorted(len(CIT_SURF[p][l - 1]) for _, p, l in (CIT_SAVED + CIT_BARE + CIT_ROW_BARE + CIT_ROW_SAVED))
_q16 = lambda f: _hitlens[min(len(_hitlens) - 1, int(f * len(_hitlens)))] if _hitlens else 0  # noqa: E731
_row_only = sorted(set(CIT_ROW_SAVED) - set(CIT_SAVED))     # 收紧方向：整行绿 → 段内红
_sent_only = sorted(set(CIT_SAVED) - set(CIT_ROW_SAVED))    # 放宽方向：整行红 → 段内绿（跨行软折句）
print(f"  长行暴露面（常驻读数，判据不吃它，只证『整行』这个单位今天还剩多少债）："
      f"命中处的物理行长度 中位 {_q16(.5)}｜p90 {_q16(.9)}｜最长 {max(_hitlens) if _hitlens else 0} 字符"
      f"｜整行单位救回 {len(CIT_ROW_SAVED)} 处 vs 段内同句救回 {len(CIT_SAVED)} 处")
print(f"      两向对账（第卅七发 C 的教训：只报一个方向等于没对账）："
      + (f"收紧 整行绿→段内红 {len(_row_only)} 处（这些位置从这一发起**算裸引用**，正文必须改措辞而不是改规则）"
         f"｜放宽 整行红→段内绿 {len(_sent_only)} 处（名字与声明词跨行软折成同句 ⇒ 这一口径比整行**松**的地方，"
         f"它守住的是段而不是行）"
         if _row_only or _sent_only else
         f"两向都是 0 处——收紧方向（整行绿→段内红）由第卅八发 E 把落笔时测出的 9 处**改措辞付清**"
         "（9 处点名由 8 处改动付清，其中一处是同一句里两个名字；一处豁免没加、词表一个词没动）；"
         "放宽方向（整行红→段内绿）本轮实测也是 0 ⇒ 今天这两个单位在正文上**逐处等价**，"
         "换了口径没有偷偷少判任何一处"))
for _nm, _pth, _ln in _row_only[:6]:
    print(f"      ·（收紧）{_nm} @{_pth}:{_ln}（行长 {len(CIT_SURF[_pth][_ln - 1])}）")
for _nm, _pth, _ln in _sent_only[:6]:
    print(f"      ·（放宽）{_nm} @{_pth}:{_ln}（行长 {len(CIT_SURF[_pth][_ln - 1])}）")
if len(_row_only) > 6:
    print(f"      ·（收紧·其余 {len(_row_only) - 6} 处同上，整改时按这份名单逐条点名）")
if len(_sent_only) > 6:
    print(f"      ·（放宽·其余 {len(_sent_only) - 6} 处同上）")
if not cited_denominator_ok(CIT_TRACKED):
    fails.append(f"闸⑯（分母自证）`git ls-files` 现读只回 {len(CIT_TRACKED)} 本、名单里没有本模块的"
                 " `_red_v3.py` ⇒ 少了 `.` 那个 pathspec 时 git 是把引用面参数当**过滤**用的，"
                 "于是全目录在册件都会被点名成『库外断链』——那种红是闸自己的债，不是正文的债")

if MODE == "--citedlink":
    inj = "_tmp_r30_injected_" + "legA.log"
    src_a = {"__注入A__": ["首行", f"三份读数各有原件 `{inj}` 与另一份", "末行"]}
    src_b = {"__注入B__": ["首行", f"三份读数各有本机原件 `{inj}` 与另一份", "末行"]}
    red_a = cited_scan(src_a, cited_universe(src_a)[0])[0]
    if sorted(x[0] for x in red_a) == [inj]:
        fails.append(f"闸⑯（--citedlink 腿A 注入的凭据）{red_a[0][1]}:{red_a[0][2]} 用反引号引用了库外"
                     f"一次性件 {inj} 而含名字那一句无声明 ⇒ 这条闸认得**新造**的断链（点名由注入决定，不是复述旧账）")
    else:
        fails.append(f"闸⑯（--citedlink 腿A）注入一条裸引用，测得点名 {sorted(x[0] for x in red_a)}"
                     f"（要恰好点名 {inj} 一处）⇒ 这条闸看不见新造的断链，它只是在复述旧账")
    red_b = cited_scan(src_b, cited_universe(src_b)[0])[0]
    if red_b:
        fails.append(f"闸⑯（--citedlink 腿B 反对照）同一条引用只多了『本机』二字，测得仍红 "
                     f"{len(red_b)} 条（要 0）⇒ 判据吃的不是那句声明，修法会被推歪成删引用")
    else:
        print(f"  腿B 同一条引用 + 『本机』⇒ 测得红 {len(red_b)} 条（期望 0）——声明本身在承重")
    if not CIT_SAVED:
        fails.append("闸⑯（--citedlink 腿C）盘上一条『靠声明才绿』的引用都读不到 ⇒ 腿C 此刻空转，"
                     "不许记成通过（声明全被删了，或正文换了写法而这条闸看不见）")
    else:
        nm0, p0, l0 = CIT_SAVED[0]
        red_c = [x for x in cited_scan(CIT_SURF, CIT_HITS, strip_win=(p0, l0))[0] if x == (nm0, p0, l0)]
        if red_c:
            fails.append(f"闸⑯（--citedlink 腿C 注入的凭据）抹掉 {p0}:{l0}（引用 {nm0}）±2 行里的声明之后"
                         f"这一处翻红（命中 {len(red_c)} 条）⇒ 那一句『不在库里』是唯一承重的东西")
        else:
            fails.append(f"闸⑯（--citedlink 腿C）把 {p0}:{l0}（引用 {nm0}）±2 行窗口里的声明全部抹掉之后"
                         f"测得这一处翻红 {len(red_c)} 条（要 ≥1）⇒ 它的绿不是声明给的，是被别的腿顶掉了")
    bad = _git_tracked(_ROOT_DOCS, use_dot=False)
    if cited_denominator_ok(bad):
        fails.append(f"闸⑯（--citedlink 腿D 反对照）少了 `.` 那个 pathspec 仍读到 {len(bad)} 本在册、"
                     "名单里含 `_red_v3.py` ⇒ 那条分母自证腿恒绿，抓不住本发实测过的坏法")
    else:
        sb = cited_surfaces(bad)
        hb = cited_universe(sb, {p.rsplit("/", 1)[-1] for p in bad})[0]
        bb = [x for x in cited_scan(sb, hb)[0] if x[0] == "_red_v3.py"]
        if not bb:
            fails.append(f"闸⑯（--citedlink 腿D）名单塌成 {len(bad)} 本、引用面 {len(sb)} 本时，"
                         "测得『把在册件当断链』0 条（要 ≥1）⇒ 这个坏法不会把在册件点名，"
                         "分母自证那条腿也就没有东西可自证")
        else:
            fails.append(f"闸⑯（--citedlink 腿D 注入的凭据）换成少了 `.` 的旧写法读在册 ⇒ 名单只剩 "
                         f"{len(bad)} 本（引用面 {len(sb)} 本），闸⑯ 当场把在册的 `_red_v3.py` 当库外断链"
                         f"点名 {len(bb)} 条，而同一个状态下分母自证那条腿也红 ⇒ 名单塌了不会被读成"
                         "『正文欠声明』")
    inj_e = "_tmp_r31_injected_" + "legE.log"
    other_e = "_tmp_r31_injected_" + "otherleg.log"
    src_e = {"__注入E__": [f"本机一次性件 `{other_e}` 在清理清单里、不在库里。",
                           f"三份读数各有原件 `{inj_e}` 与另一份。",
                           "这一段只算叙述级，clone 之后取不到"]}
    red_e = cited_scan(src_e, cited_universe(src_e)[0])[0]
    if sorted(x[0] for x in red_e) == [inj_e]:
        fails.append(f"闸⑯（--citedlink 腿E 注入的凭据）±2 行内声明词一条不缺（本机/清理清单/不在库里/"
                     f"叙述级），但它们点的是**另一个**名字 {other_e}，而句边界把两件事分在两句里"
                     f"⇒ 被引用的 {inj_e} 测得仍红 {len(red_e)} 条——承重的是『点名』而不是『标记词在场』"
                     f"（第卅八发 E 把单位收到句一级之后，这个夹具**必须带句边界**：去掉句号两行会拼成同句，"
                     f"别人那句声明会顺带把 {inj_e} 救绿，那正是腿F 要防的反面）")
    else:
        fails.append(f"闸⑯（--citedlink 腿E）注入『标记词在场但没点名』的三行，测得点名 "
                     f"{sorted(x[0] for x in red_e)}（要恰好 {inj_e}）⇒ 点名式判据没生效，"
                     f"别人那句话还在替这条断链作保")
    src_f = {"__注入F__": [f"本机一次性件 `{inj_e}`：不在库里，clone 之后取不到",
                           f"三份读数各有原件 `{inj_e}` 与另一份",
                           "末行"]}
    red_f = cited_scan(src_f, cited_universe(src_f)[0])[0]
    if red_f:
        fails.append(f"闸⑯（--citedlink 腿F 反对照）点名式声明写在**相邻行**（±2 行窗口内、同一段），"
                     f"测得仍红 {len(red_f)} 条（要 0）⇒ 收紧把窗口当成了『同一行』，正文会被逼成把声明"
                     f"挤进引用行，那是改写法不是改事实")
    else:
        print(f"  腿F 点名声明写在相邻行 ⇒ 测得红 {len(red_f)} 条（期望 0）——窗口仍是 ±2 行")
    inj_g = "_tmp_r31_injected_" + "legG.log"
    src_g = {"__注入G__": ["首行",
                           f"读数当时本机有 21 个并存的 python 进程，而原件 `{inj_g}` 停在 7/8",
                           "末行"]}
    red_g = cited_scan(src_g, cited_universe(src_g)[0])[0]
    if red_g:
        fails.append(f"闸⑯（--citedlink 腿G）注入的是『名字与声明词同现于一行、但那个词修饰的是别的东西』，"
                     f"测得这一处**已能红**（{len(red_g)} 条）⇒ 判据比头部那句盲区申报更严了，"
                     f"文件头与红句里『同现不同述看不见』那句必须按现读改写，不许留着过期申报")
    else:
        print(f"  腿G 名字与声明词同现于一行但不同述 ⇒ 测得红 {len(red_g)} 条（期望 0）——这是本闸的已知盲区，"
              f"第卅一发在 README:1158 现读到活的一例（那行的『本机』修饰的是并存进程数，不是那本日志）")
    # 腿H（第卅二发·结第卅一发新欠⑵）：词表是**闭表**这件事要有自己的红。
    inj_h = "_tmp_r32_injected_" + "legH.log"
    src_h = {"__注入H__": ["首行", f"三份读数各有原件 `{inj_h}`（{_SENTINEL_MARK}）", "末行"]}
    src_h2 = {"__注入H反__": ["首行", f"三份读数各有原件 `{inj_h}`（本机）", "末行"]}
    red_h = cited_scan(src_h, cited_universe(src_h)[0])[0]
    red_h2 = cited_scan(src_h2, cited_universe(src_h2)[0])[0]
    if _LOCAL_MARK.search(_SENTINEL_MARK):
        print(f"  腿H 的声明词此刻**已在**词表里 ⇒ 测得红 {len(red_h)} 条；同一件事已由常驻哨兵那条红点名，"
              f"本腿不重复计数（第卅一发新欠⑵要防的正是『加词悄无声息』，不是这条注入本身）")
    elif sorted(x[0] for x in red_h) == [inj_h]:
        fails.append(f"闸⑯（--citedlink 腿H 注入的凭据）注入一句**真声明**、用的词（『{_SENTINEL_MARK}』）却不在"
                     f"`_LOCAL_MARK` 现读 {_nmark16} 个词里 ⇒ 测得恰好点名 {inj_h} 一处红。这句话变绿只有两条路："
                     f"把正文改成表内的措辞（正文的债，由 ⑯ 的裸引用红管），或往表里加词（点亮常驻哨兵那条红）"
                     f"——『改正文』与『加词』各有自己的红，这就是第卅一发那句『守卫里没有任何一档会因为词表"
                     f"被加宽而红』的还法")
    else:
        fails.append(f"闸⑯（--citedlink 腿H）注入『词表外同义词的声明』，测得点名 "
                     f"{sorted(x[0] for x in red_h)}（要恰好 {inj_h} 一处）⇒ 这条腿没抓到：词在不在表里对闸"
                     f"不构成区别，下一次加词照样悄无声息")
    if red_h2:
        fails.append(f"闸⑯（--citedlink 腿H 反对照）同一句只把声明词换成表内的『本机』，测得仍红 "
                     f"{len(red_h2)} 条（要 0）⇒ 红的不是词表，判据已经坏到连表内声明都不认，"
                     f"这条腿的凭据也就说不出『加词』这件事")
    else:
        print(f"  腿H 反对照：同句改用表内『本机』⇒ 测得红 {len(red_h2)} 条（期望 0）——"
              f"这条腿吃的确实只是『词在不在表里』")
else:
    for nm, path, ln in CIT_BARE:
        fails.append(f"闸⑯（断链引用）{path}:{ln} 用反引号引用了库外一次性件 {nm}，±2 行那一段里"
                     "**含这个名字的那一句**没有写出『" + _LOCAL_MARK.pattern.replace("|", "/") + "』任一句"
                     " ⇒ clone 之后这句话指着不存在的原件（把声明写成点名的，或改成命令形态的凭据）")
    if not CIT_HITS:
        fails.append("闸⑯ 一条库外一次性件引用都没读到 ⇒ 不是通过，是没测到"
                     "（glob 空转，或正文换了写法而这条闸看不见）")

# --longline 的专属拆红（第卅八发 E·还新欠⑸）：把『一整发行』这个形状**造出来**。
# 注入是一篇"一行=一篇文档"的正文：名字所在的那句**没有**声明词，声明词（『本机』）住在**同一行的
# 另一句**里、说的是别的东西。旧单位（整行）会把它救回 ⇒ 这条红必须是**换了判定单位才抓得到**的，
# 否则这一档和普通缺声明的注入（腿A）没区别，也就证不了"长行失明"这件事。
if MODE == "--longline":
    inj_l = "_tmp_r38_injected_" + "longline.log"
    _fill = "、".join(f"读数{i}" for i in range(1500))          # 撑长那一行；不含任何声明词
    src_l = {"__注入长行__": [f"那一发把全部读数写在了一行里：{_fill}。原件 `{inj_l}` 停在第 7 条流"
                              f"、没有第八条。{_fill[:1200]}。同期的本机还跑着别的进程，与这条引用无关。"]}
    src_l2 = {"__注入长行反__": [f"那一发把全部读数写在了一行里：{_fill}。原件 `{inj_l}` 是本机一次性件、"
                                 f"停在第 7 条流、没有第八条。{_fill[:1200]}。"]}
    _hits_l = cited_universe(src_l)[0]
    _row_l = cited_scan_row(src_l, _hits_l)
    _sen_l = cited_scan(src_l, _hits_l)
    _sen_l2 = cited_scan(src_l2, cited_universe(src_l2)[0])
    if _row_l[0]:
        fails.append(f"闸⑯（长行失明·注入的形状）这一档的注入本应是**旧单位放行**的形状，实测整行单位也把它"
                     f"判成裸引用 {_row_l[0]} ⇒ 这句红来自『缺声明』而不是『判定单位』，档位测错了对象")
    if sorted(x[0] for x in _sen_l[0]) == [inj_l]:
        fails.append(f"闸⑯（长行失明·注入的凭据）注入把整发写成一发行（"
                     f"{len(src_l['__注入长行__'][0])} 字符），名字所在那句没有声明词、声明词『本机』在同行的另一句里"
                     f" ⇒ 段内同句单位点名 {inj_l} 一处红；同一处在**整行单位**下是绿的（上面那条反证）"
                     f"⇒ 这条腿确实守着『一行=一篇文档』那一型")
    else:
        fails.append(f"闸⑯（长行失明）注入『名字与声明词同一物理行、分属两句』，段内同句单位测得点名 "
                     f"{sorted(x[0] for x in _sen_l[0])}（要恰好 {inj_l} 一处）⇒ 这条腿没牙，"
                     f"『整行等于没判』那一型照样绿")
    if _sen_l2[0]:
        fails.append(f"闸⑯（长行失明 反对照）同一行只把『本机』挪进名字所在的那一句，段内同句单位测得仍红 "
                     f"{len(_sen_l2[0])} 条（要 0）⇒ 判据吃的不是句子归属，收紧会一路红到把正文逼成删引用")
    _onleg = [f for f in fails if "闸⑯（长行失明" in f]
    _body = [f for f in fails if f.startswith("闸⑯（断链引用）")]
    _other = [f for f in fails if "闸⑯（长行失明" not in f and f not in _body]
    _ev = [f for f in _onleg if "·注入的凭据）" in f]
    print(f"\n[--longline 专属校验] 注入的长行 {len(src_l['__注入长行__'][0])} 字符 × 1 行；"
          f"整行单位救回 {len(_row_l[1])} 处、段内同句救回 {len(_sen_l[1])} 处；"
          f"反对照 ⇒ 段内同句救回 {len(_sen_l2[1])} 处"
          f"｜另有 {len(_body)} 条**正文自己的**断链引用红（常驻判据点名的，不算注入走漏）")
    if len(_ev) != len(_sen_l[0]):
        fails.append(f"闸⑯（长行失明）这条腿的注入凭据 {len(_ev)} 条而注入里被单位差额救回的点有 "
                     f"{len(_sen_l[0])} 处⇒ 处数对红的锁步断了，这一档的读数不能当档位强度用")
    if _other:
        fails.append(f"闸⑯（长行失明）{len(_other)} 条红既不在本条腿上、也不是正文的断链引用红"
                     f"（{sorted({f.split('：')[0] for f in _other})[:3]}）⇒ 注入走漏到别的判据")


# 常驻哨兵（第卅二发·normal 与每一档都跑）：加词必须点亮一条红。
if _LOCAL_MARK.search(_SENTINEL_MARK):
    fails.append(f"闸⑯（词表哨兵·常驻）声明词表 `_LOCAL_MARK` 现读 {_nmark16} 个词，里面已经含哨兵词"
                 f"『{_SENTINEL_MARK}』⇒ **有人在加词**。第卅一发量过加词的代价：新增两词让 ⑯ 报的 14 条"
                 f"裸引用变绿，而那一发守卫里没有任何一档会因为加词而红（新欠⑵），这条就是那笔欠的还法。"
                 f"二选一：① 把这词撤出表，正文改用表内的措辞——那就是正文的债，由 ⑯ 的裸引用红点名；"
                 f"② 确认它是承重的同义词，那就照第卅一发那次量一遍『这个词替几处作了保』（HEAD 词表 vs "
                 f"现词表两遍 `normal` 对照），把数字写进 README 最新一发，并把 `_SENTINEL_MARK` 换成另一个"
                 f"**仍在表外**的真声明词——哨兵必须常设，撤掉它等于把这条腿一起撤掉。")
else:
    print(f"  词表哨兵（常驻，normal 与每一档都跑）：真声明词『{_SENTINEL_MARK}』在词表**外**"
          f"（现读 {_nmark16} 个词）⇒ 把它收进表的那一行 diff 会同时点亮上面这条红")


# --namecut 的专属校验（第卅七发 C）：这一档的注入**只动"印出几件"**、不动任何判据的输入
# ⇒ 它该只点亮上面那条对账腿。冒出别的闸的红就说明注入走漏了，这一档就不是"只测这条腿"的档。
if MODE == "--namecut":
    _cut = [x for x in _named if x[2] != x[3]]
    _onleg = [f for f in fails if "·点名对账" in f]
    _noname = [f for f in fails if "·点名对账" not in f]
    print(f"\n[--namecut 专属校验] 名单 ≥2 件因而被印漏一件的点名句 = {len(_cut)} 处"
          f"（测得对账腿的红 {len(_onleg)} 条，期望与处数相等；另有 {len(_noname)} 条红不住在这条腿上）")
    if not _cut:
        fails.append("闸⑥／⑦／⑧（--namecut）一处『名单 ≥2 件』的点名句都没有 ⇒ 注入没处放，这条红不算通过")
    if len(_onleg) != len(_cut):
        fails.append(f"闸⑥／⑦／⑧（--namecut）对账腿红了 {len(_onleg)} 条而被注入的点名句有 {len(_cut)} 处"
                     f"⇒ 一条处数对一条红的锁步断了，这条腿的读数不能当档位强度用")
    if _noname:
        fails.append(f"闸⑥／⑦／⑧（--namecut）{len(_noname)} 条红不住在新加的对账腿上"
                     f"（{sorted({f.split('：')[0] for f in _noname})[:3]}）⇒ 注入走漏到别的判据")
    if _extra:
        fails.append(f"闸⑥／⑦／⑧（--namecut）这一档的注入只可能把印出件数**调少**，却测出 {len(_extra)} 处"
                     f"『印出 > 名单』的多印红 ⇒ 方向分支被别的档串进来了（或 `_pm` 的两个分支互相污染），"
                     f"这一档的红不再只对应『印漏』这一种输入")


# --nameextra 的专属校验（第卅八发 C，还新欠⑶）：与 --namecut 互为反向——这一档的注入**只把印出件数调多**
# （复制最后一件），头上那个 `len()` 一样不动 ⇒ 它该只点亮对账腿，且每条红都落在『多印』方向。
if MODE == "--nameextra":
    _ex = [x for x in _named if x[3] > x[2]]
    _onleg = [f for f in fails if "·点名对账" in f]
    _noname = [f for f in fails if "·点名对账" not in f]
    print(f"\n[--nameextra 专属校验] 名单 ≥2 件因而被多印一件的点名句 = {len(_ex)} 处"
          f"（测得对账腿的红 {len(_onleg)} 条，期望与处数相等；另有 {len(_noname)} 条红不住在这条腿上）")
    if not _ex:
        fails.append("闸⑥／⑦／⑧（--nameextra）一处『名单 ≥2 件』的点名句都没有 ⇒ 反向注入没处放，这条红不算通过")
    if len(_onleg) != len(_ex):
        fails.append(f"闸⑥／⑦／⑧（--nameextra）对账腿红了 {len(_onleg)} 条而被注入的点名句有 {len(_ex)} 处"
                     f"⇒ 一条处数对一条红的锁步断了，这条腿的读数不能当档位强度用")
    if _noname:
        fails.append(f"闸⑥／⑦／⑧（--nameextra）{len(_noname)} 条红不住在对账腿上"
                     f"（{sorted({f.split('：')[0] for f in _noname})[:3]}）⇒ 反向注入走漏到别的判据")
    if _miss:
        fails.append(f"闸⑥／⑦／⑧（--nameextra）这一档的注入只可能把印出件数**调多**，却测出 {len(_miss)} 处"
                     f"『印出 < 名单』的印漏红 ⇒ 两个方向的分支没分开，反方向的白拿会顶掉真信号")


print(f"\n模式：{MODE or '（正常验红）'}")
if fails:
    print(f"\n>>> 验红 {len(fails)} 条红：")
    for f in fails:
        print("   ", f)
    raise SystemExit(1)
print("\n结论：v3 只买『判据看得见阶梯顶』这一件事，v4 只买『出界的份额话改口成倒挂』这一件事"
      "——其余各本判词逐字不动。")
